CREATE TRIGGER wl_web_talk_seen_d AFTER DELETE ON wl_talk_seen WHEN NOT EXISTS (SELECT 1 FROM wl_mute) BEGIN INSERT INTO wl_change(tbl, pk, op, at, origin, tx) VALUES ('talk_seen', json_array(OLD."who", OLD."chan", OLD."thread"), 'del', CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER), 'web', (SELECT tx FROM wl_tx LIMIT 1)); END;
